#### **`app.py`**
```python
from flask import Flask, jsonify, request
from database import init_db, get_db
from models import create_reservation, get_reservations

app = Flask(__name__)
init_db()

@app.route('/reservations', methods=['POST'])
def add_reservation():
    data = request.json
    name = data.get('name')
    date = data.get('date')
    guest_count = data.get('guest_count')

    create_reservation(name, date, guest_count)
    return jsonify({'message': 'Reservation created successfully'}), 201

