#### **`models.py`**
```python
from database import get_db

def create_reservation(name, date, guest_count):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('''
        INSERT INTO reservations (name, date, guest_count)
        VALUES (?, ?, ?)
    ''', (name, date, guest_count))
    conn.commit()
    conn.close()

def get_reservations():
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute('SELECT * FROM reservations')
    reservations = cursor.fetchall()
    conn.close()
    return [dict(res) for res in reservations]
```

